 const c=state.company||{},name=[c.directorName,c.directorSurname].filter(Boolean).join(' ');
 return `<div class="box"><div class="boxt">DIRECTOR TÉCNICO</div><div class="boxb director-combined"><div><b>Nombre:</b> ${esc(name||'—')}</div><div class="director-media"><b>Firma y sello:</b>${c.directorSignature?`<img class="sigimg" src="${c.directorSignature}" alt="Firma">`:''}${c.seal?`<img src="${c.seal}" alt="Sello">`:''}</div></div></div>`;
