 const docs=`<div class="grid2"><div class="box"><div class="boxt">ENTRADA Y SALIDA DE MADERA</div><div class="boxb kv"><b>Albarán entrada:</b><span>${esc(d.clientDeliveryNo||d.entryDeliveryNo||'—')}</span><b>Fecha entrada:</b><span>${esc(d.entryDate||'—')}</span><b>Albarán salida / entrega:</b><span>${esc(d.exitDeliveryNo||'—')}</span><b>Fecha salida:</b><span>${esc(d.exitDate||'—')}</span></div></div><div class="box"><div class="boxt">DOCUMENTACIÓN DEL CICLO ADJUNTA</div><div class="boxb">${d.cycleDoc?'☑':'☐'} Registro / gráfica del ciclo<br>${d.productCertificate?'☑':'☐'} Certificado del producto<br>${d.cycleOtherDoc?`☑ ${esc(d.cycleOtherDoc)}`:'☐ Otros'}</div></div></div>`;
 const photo=s.photos?.before?`<div class="box"><div class="boxt">FOTOGRAFÍA DEL MATERIAL</div><div class="boxb"><img class="photo" src="${s.photos.before}" alt="Material"></div></div>`:'';
 legacyAutoWindow('HOJA DE SERVICIO - TRATAMIENTO DE MADERA EN AUTOCLAVE',`<div class="docmeta"><b>N.º hoja:</b> ${esc(s.number||'')} &nbsp; <b>Fecha:</b> ${esc(s.date||'')}</div>${clientClassicBox(s)}${material}${cycle}${docs}<div class="grid2">${photo}<div class="box"><div class="boxt">OBSERVACIONES</div><div class="boxb note">${esc(d.autoObs||'')}</div></div></div>${directorCombinedBox()}`);
