function setupInkCanvas(canvas,existing,clearButton){
 const ctx=canvas.getContext('2d');ctx.lineWidth=3;ctx.lineCap='round';ctx.strokeStyle='#17221c';let drawing=false,hasInk=false;
 const pos=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};
 canvas.onpointerdown=e=>{drawing=true;const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);try{canvas.setPointerCapture(e.pointerId)}catch{}e.preventDefault()};canvas.onpointermove=e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke();hasInk=true;e.preventDefault()};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;
 if(existing){const im=new Image();im.onload=()=>{ctx.drawImage(im,0,0,canvas.width,canvas.height);hasInk=true};im.src=existing}
 if(clearButton)clearButton.onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);hasInk=false};canvas._hasInk=()=>hasInk;canvas._data=()=>canvas.toDataURL('image/png');
}
