function ensureMobiliarioInvoice(s){const d=s.data=s.data||{},inv=d.furnInvoice=d.furnInvoice||{};if(!inv.number)inv.number=serviceDocNo(s,'FRA');if(!inv.date)inv.date=nowDate();if(!Array.isArray(inv.lines)||!inv.lines.length){const qty=(ensureFurnLines(s).reduce((a,x)=>a+(num(x.qty)||0),0)||num(d.furnQty)||1),price=num(d.furnUnitPrice)||0;inv.lines=[{ref:String(s.number||'MOB').replace(/\s+/g,''),description:'Tratamiento de mobiliario',detail:furnTreatmentLabels(d),qty:String(qty||''),price:price?String(price):'',discount:'0',vat:'21'}]}inv.status=inv.status||'BORRADOR';return inv}
